// Helper to generate future deadlines relative to "now"
function futureDate(monthsFromNow: number, day: number = 15): string {
  const d = new Date();
  d.setMonth(d.getMonth() + monthsFromNow);
  d.setDate(day);
  return d.toISOString().split('T')[0];
}

